   "  request_hash    TEXT   NOT NULL,                -- hash do corpo",
   "  recovery_point  TEXT   NOT NULL DEFAULT 'started',",
   "  locked_at       TIMESTAMPTZ DEFAULT now(),      -- NULL: ninguém trabalhando",
